local GardenSprayerMaker = {}
local PRODUCTS = {
    iron_gardensprayer = { name = "Železni vrtna škropilnica", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vrtna škropilnica za vrtnarje." },
    bronze_gardensprayer = { name = "Bronast vrtna škropilnica", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vrtna škropilnica za vrtnarje." },
    silver_gardensprayer = { name = "Srebrn vrtna škropilnica", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vrtna škropilnica za vrtnarje." },
    gilded_gardensprayer = { name = "Pozlačen vrtna škropilnica", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vrtna škropilnica za vrtnarje." },
    jewel_set_gardensprayer = { name = "Draguljast vrtna škropilnica", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vrtna škropilnica za vrtnarje." },
    royal_sovereign_gardensprayer = { name = "Kraljevski suveren vrtna škropilnica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vrtna škropilnica z biseri za krono." },
}
local BUILDINGS = {
    gardensprayer_workshop = { name = "Gardensprayer delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gardensprayer_house = { name = "Gardensprayer hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gardensprayer_atelier = { name = "Mojstrski gardensprayer atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gardensprayer_palace = { name = "Suverena gardensprayer palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenSprayerMaker.ironStock=12; GardenSprayerMaker.bronzeStock=10; GardenSprayerMaker.woodStock=14; GardenSprayerMaker.leatherStock=12; GardenSprayerMaker.silverStock=8; GardenSprayerMaker.goldStock=6; GardenSprayerMaker.jewelStock=4; GardenSprayerMaker.pearlStock=4
GardenSprayerMaker.productStock = {}; GardenSprayerMaker.buildings = {}; GardenSprayerMaker.maker = nil; GardenSprayerMaker.activeMaking = {}; GardenSprayerMaker.totalProducts = 0; GardenSprayerMaker.dayTimer = 0
function GardenSprayerMaker.init() GardenSprayerMaker.ironStock=12; GardenSprayerMaker.bronzeStock=10; GardenSprayerMaker.woodStock=14; GardenSprayerMaker.leatherStock=12; GardenSprayerMaker.silverStock=8; GardenSprayerMaker.goldStock=6; GardenSprayerMaker.jewelStock=4; GardenSprayerMaker.pearlStock=4; GardenSprayerMaker.productStock={}; GardenSprayerMaker.buildings={}; GardenSprayerMaker.maker=nil; GardenSprayerMaker.activeMaking={}; GardenSprayerMaker.totalProducts=0; GardenSprayerMaker.dayTimer=0; print("[GardenSprayerMaker] Royal Garden Sprayer Maker System initialized (6 products, 4 buildings)") end
function GardenSprayerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenSprayerMaker.maker={name=n or ("Škropičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škropičar najet: %s (spretnost: %d)",GardenSprayerMaker.maker.name,s),"success") end; return true end
function GardenSprayerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenSprayerMaker.build(id) local ok,e=GardenSprayerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenSprayerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenSprayerMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenSprayerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenSprayerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenSprayerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenSprayerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenSprayerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenSprayerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenSprayerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenSprayerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenSprayerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenSprayerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenSprayerMaker.buildings==0 then return false,"Potrebna škropilna delavnica" end; if not GardenSprayerMaker.maker then return false,"Potreben škropičar" end; return true end
function GardenSprayerMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenSprayerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenSprayerMaker.ironStock=GardenSprayerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenSprayerMaker.bronzeStock=GardenSprayerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenSprayerMaker.woodStock=GardenSprayerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenSprayerMaker.leatherStock=GardenSprayerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenSprayerMaker.silverStock=GardenSprayerMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenSprayerMaker.goldStock=GardenSprayerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenSprayerMaker.jewelStock=GardenSprayerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenSprayerMaker.pearlStock=GardenSprayerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenSprayerMaker.maker then t=math.max(1,t-math.floor(GardenSprayerMaker.maker.skill/13)) end; table.insert(GardenSprayerMaker.activeMaking,{id="gardensprayer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenSprayerMaker.completeMaking(m) local q=1.0+(GardenSprayerMaker.getQualityBonus()/100); if GardenSprayerMaker.maker then q=q+(GardenSprayerMaker.maker.skill/140) end; q=math.min(2.5,q); GardenSprayerMaker.productStock[m.productType]=(GardenSprayerMaker.productStock[m.productType] or 0)+m.quantity; GardenSprayerMaker.totalProducts=GardenSprayerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenSprayerMaker.maker then GardenSprayerMaker.maker.itemsMade=GardenSprayerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenSprayerMaker.maker.skill=math.min(100,GardenSprayerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škropilnica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardensprayer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenSprayerMaker.update(dt) if not _G.state then return end; GardenSprayerMaker.dayTimer=GardenSprayerMaker.dayTimer+dt; if GardenSprayerMaker.dayTimer>=30 then GardenSprayerMaker.dayTimer=0; for i=#GardenSprayerMaker.activeMaking,1,-1 do local m=GardenSprayerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenSprayerMaker.completeMaking(m); table.remove(GardenSprayerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenSprayerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenSprayerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenSprayerMaker.getStats() return {ironStock=GardenSprayerMaker.ironStock,bronzeStock=GardenSprayerMaker.bronzeStock,woodStock=GardenSprayerMaker.woodStock,leatherStock=GardenSprayerMaker.leatherStock,silverStock=GardenSprayerMaker.silverStock,goldStock=GardenSprayerMaker.goldStock,jewelStock=GardenSprayerMaker.jewelStock,pearlStock=GardenSprayerMaker.pearlStock,productStock=GardenSprayerMaker.productStock,numBuildings=#GardenSprayerMaker.buildings,hasMaker=GardenSprayerMaker.maker~=nil,makerName=GardenSprayerMaker.maker and GardenSprayerMaker.maker.name or "—",makerSkill=GardenSprayerMaker.maker and GardenSprayerMaker.maker.skill or 0,activeMaking=#GardenSprayerMaker.activeMaking,totalProducts=GardenSprayerMaker.totalProducts} end
return GardenSprayerMaker
